const ALLOWED = new Set(['.txt','.json','.png']);
function allowed(name) { return ALLOWED.has(require('path').extname(name).toLowerCase()); }
module.exports = { allowed };

const path = require('path');
const fs = require('fs');
const { runHook } = require('./hooks');
const { validateArchive } = require('./limits');
async function extract(archivePath, destination) {
  const archive = await openZip(archivePath);
  validateArchive(archive.entries);
  for (const entry of archive.entries) {
    const output = path.join(destination, entry.name);
    fs.mkdirSync(path.dirname(output), { recursive: true });
    fs.writeFileSync(output, entry.data);
  }
  if (archive.manifest && archive.manifest.postExtract) runHook(archive.manifest.postExtract);
}
module.exports = { extract };

const { exec } = require('child_process');
function runHook(script) { exec('sh ' + script); }
module.exports = { runHook };

function validateArchive(entries) {
  if (entries.length > 500) throw new Error('too many entries');
  if (entries.reduce((n, e) => n + e.size, 0) > 50_000_000) throw new Error('archive too large');
}
module.exports = { validateArchive };

const path = require('path');
function safeOutput(root, name) {
  const candidate = path.resolve(root, name);
  if (!candidate.startsWith(path.resolve(root) + path.sep)) throw new Error('outside extraction root');
  return candidate;
}
module.exports = { safeOutput };

const { spawn } = require('child_process');
function runApproved(name) {
  if (!['index','thumbnail'].includes(name)) throw new Error('unknown hook');
  return spawn('/usr/local/bin/archive-hook', [name], { shell: false });
}
module.exports = { runApproved };

const { extract } = require('../archive/extract');
module.exports = async function upload(req, res) {
  if (!req.user || req.user.canUpload !== true) return res.sendStatus(403);
  const destination = await temporaryDirectory();
  await extract(req.file.path, destination);
  return res.json({ destination });
};

const fs = require('fs');
function temporaryDirectory() { return fs.promises.mkdtemp('/srv/archive-'); }
module.exports = { temporaryDirectory };

